// Shared helpers for every workflow's Code nodes.
//
// `npm run build` concatenates this file in front of each workflow module when it
// embeds them into n8n Code nodes (the EXPORT tail is stripped), so everything
// here must run unchanged inside n8n's Code-node sandbox: no `require`, no
// Node-only globals, and plain JavaScript only.

// Two-label public suffixes for the target countries. This is deliberately not
// the full Public Suffix List; anything not listed is treated as a one-label suffix.
const MULTI_LABEL_SUFFIXES = new Set([
  'co.uk', 'org.uk', 'me.uk', 'ltd.uk', 'plc.uk', 'net.uk', 'ac.uk', 'gov.uk', 'sch.uk', 'nhs.uk',
  'com.au', 'net.au', 'org.au', 'id.au', 'asn.au',
  'co.nz', 'org.nz', 'net.nz',
  'ab.ca', 'bc.ca', 'mb.ca', 'nb.ca', 'nl.ca', 'ns.ca', 'nt.ca', 'nu.ca', 'on.ca', 'pe.ca', 'qc.ca', 'sk.ca', 'yk.ca',
]);

// Shared mailbox providers. A suppressed address at one of these must never
// suppress every other user of the provider, and an agency using one gets a warning.
const FREE_MAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'hotmail.co.uk', 'outlook.com', 'live.com',
  'live.co.uk', 'msn.com', 'yahoo.com', 'yahoo.co.uk', 'ymail.com', 'icloud.com', 'me.com',
  'aol.com', 'aol.co.uk', 'btinternet.com', 'btopenworld.com', 'sky.com', 'virginmedia.com',
  'talktalk.net', 'ntlworld.com', 'blueyonder.co.uk', 'mail.com', 'gmx.com', 'gmx.co.uk',
  'protonmail.com', 'proton.me', 'zoho.com', 'bigpond.com', 'optusnet.com.au', 'shaw.ca',
  'rogers.com', 'sympatico.ca',
]);

// Lead stages, exactly as in docs/02-mvp-architecture.md §4.
const STAGE = {
  NEW: 'New Lead',
  RESEARCHED: 'Researched',
  QUALIFIED: 'Qualified',
  DISQUALIFIED: 'Disqualified',
  DRAFT_READY: 'Draft Ready',
  APPROVED: 'Approved',
  CONTACTED: 'Contacted',
  REPLIED: 'Replied',
  MEETING: 'Meeting Opportunity',
  PROPOSAL: 'Proposal Sent',
  WON: 'Won',
  LOST: 'Lost',
  UNSUBSCRIBED: 'Unsubscribed',
};

function text(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function isTrue(value) {
  return value === true || text(value).toUpperCase() === 'TRUE';
}

// Returns the lower-cased hostname, or '' if the value is not a usable web address.
// With requireScheme, bare domains like "example.co.uk" are rejected.
function parseHost(value, { requireScheme = false } = {}) {
  const raw = text(value);
  if (!raw || /\s/.test(raw)) return '';
  const match = /^(?:(https?):\/\/)?([^/?#]+)(?:[/?#].*)?$/i.exec(raw);
  if (!match) return '';
  if (!match[1] && requireScheme) return '';
  let authority = match[2];
  if (authority.includes('@')) return '';
  authority = authority.replace(/:\d+$/, '');
  const host = authority.toLowerCase().replace(/\.$/, '');
  if (!host.includes('.')) return '';
  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(host)) return '';
  const labels = host.split('.');
  const labelOk = (l) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(l);
  if (!labels.every(labelOk)) return '';
  if (!/^[a-z]{2,63}$/.test(labels[labels.length - 1])) return '';
  return host;
}

function registrableDomain(host) {
  const h = text(host).toLowerCase().replace(/^www\./, '');
  if (!h) return '';
  const labels = h.split('.');
  if (labels.length <= 2) return h;
  const lastTwo = labels.slice(-2).join('.');
  return MULTI_LABEL_SUFFIXES.has(lastTwo) ? labels.slice(-3).join('.') : lastTwo;
}

function normaliseEmail(value) {
  return text(value).replace(/^mailto:/i, '').replace(/\?.*$/, '').trim().toLowerCase();
}

function isValidEmail(email) {
  if (!email || email.length > 254) return false;
  const at = email.lastIndexOf('@');
  if (at < 1 || at !== email.indexOf('@')) return false;
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  if (local.length > 64) return false;
  if (!/^[a-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[a-z0-9!#$%&'*+/=?^_`{|}~-]+)*$/.test(local)) return false;
  return domain !== '' && parseHost(domain) === domain;
}

function emailDomain(email) {
  return email.slice(email.indexOf('@') + 1);
}

// Google Sheets may return a date cell as a serial day number (days since 1899-12-30).
function normaliseDate(value) {
  if (typeof value === 'number' && value > 20000 && value < 80000) {
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000).toISOString();
  }
  const raw = text(value);
  if (!raw) return '';
  return Number.isNaN(Date.parse(raw)) ? null : raw;
}

// Milliseconds since epoch for a timestamp cell, or NaN.
function timeOf(value) {
  const d = normaliseDate(value);
  return d ? Date.parse(d) : NaN;
}

function parseSettings(settingsRows) {
  const settings = {};
  for (const row of settingsRows || []) {
    const key = text(row && row.key);
    if (key) settings[key] = row.value;
  }
  return settings;
}

// Fails closed: without a valid, active niche the calling workflow is aborted.
function resolveActiveNiche(settings, nichesRows, action = 'import') {
  const nicheId = text(settings.ACTIVE_NICHE);
  if (!nicheId) throw new Error(`Settings.ACTIVE_NICHE is missing or blank; ${action} aborted.`);
  const niche = (nichesRows || []).find((n) => n && text(n.niche_id) === nicheId);
  if (!niche) throw new Error(`ACTIVE_NICHE "${nicheId}" has no row in the Niches tab; ${action} aborted.`);
  if (!isTrue(niche.active)) throw new Error(`Niche "${nicheId}" is not active (Niches.active must be TRUE); ${action} aborted.`);
  if (!text(niche.country)) throw new Error(`Niche "${nicheId}" has no country; ${action} aborted.`);
  return { niche_id: nicheId, country: text(niche.country), row: niche };
}

// Suppression applies to the exact address and to the company domain, except
// that shared mail providers are never suppressed at domain level (§3.4).
function buildSuppressionIndex(suppressionRows) {
  const suppressedEmails = new Set();
  const suppressedDomains = new Set();
  for (const row of suppressionRows || []) {
    if (!row) continue;
    const email = normaliseEmail(row.email);
    if (email) {
      suppressedEmails.add(email);
      if (isValidEmail(email)) {
        const d = registrableDomain(emailDomain(email));
        if (!FREE_MAIL_DOMAINS.has(d)) suppressedDomains.add(d);
      }
    }
    const domain = registrableDomain(parseHost(row.domain));
    if (domain && !FREE_MAIL_DOMAINS.has(domain)) suppressedDomains.add(domain);
  }
  return { suppressedEmails, suppressedDomains };
}

// Returns '' when the contact may be used, otherwise a reason string.
function suppressionReason(index, email, leadId) {
  const e = normaliseEmail(email);
  if (e && index.suppressedEmails.has(e)) return 'contact_email is on the Suppression list';
  const lead = text(leadId).toLowerCase();
  const mailDomain = e && e.includes('@') ? registrableDomain(emailDomain(e)) : '';
  if ((lead && index.suppressedDomains.has(lead)) || (mailDomain && !FREE_MAIL_DOMAINS.has(mailDomain) && index.suppressedDomains.has(mailDomain))) {
    return 'domain is on the Suppression list';
  }
  return '';
}

// Rows from a Sheets read, minus the empty {} item n8n emits for an empty tab.
function realRows(rows) {
  return (rows || []).filter((r) => r && Object.keys(r).length > 0);
}

// Calendar parts of an instant in an IANA time zone (Intl is available both in
// Node and in the n8n Code-node sandbox; Luxon is not needed).
function zonedParts(ms, timeZone) {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  });
  const parts = Object.fromEntries(fmt.formatToParts(new Date(ms)).map((p) => [p.type, p.value]));
  return {
    weekday: parts.weekday,
    date: `${parts.year}-${parts.month}-${parts.day}`,
    minutes: Number(parts.hour) * 60 + Number(parts.minute),
  };
}

function isValidTimeZone(timeZone) {
  try {
    new Intl.DateTimeFormat('en-GB', { timeZone: text(timeZone) || 'invalid/zone' });
    return true;
  } catch (e) {
    return false;
  }
}

function clip(value, max) {
  const s = text(value);
  return s.length > max ? `${s.slice(0, max - 1)}…` : s;
}

// Evidence is stored in Leads.evidence as one line per item:  "quote" — url [signal]
function formatEvidence(items) {
  return (items || [])
    .map((e) => `"${text(e.quote).replace(/"/g, "'")}" — ${text(e.url)}${text(e.signal) ? ` [${text(e.signal)}]` : ''}`)
    .join('\n');
}

function parseEvidence(value) {
  const out = [];
  for (const line of text(value).split('\n')) {
    const m = /^"(.*)" — (\S+)(?: \[(.*)\])?$/.exec(line.trim());
    if (m) out.push({ quote: m[1], url: m[2], signal: m[3] || '' });
  }
  return out;
}

// Whole numbers 0..max written as digits (Sheets may return them as numbers).
function parseIntSetting(value, min, max) {
  const s = text(value);
  if (!/^\d+$/.test(s)) return NaN;
  const n = Number(s);
  return n >= min && n <= max ? n : NaN;
}

// Index of the input item an n8n output item came from (HTTP Request and Gmail
// nodes replace an item's JSON, so later Code nodes recover context this way).
function pairedIndex(item, fallback) {
  const p = item && (Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem);
  return p && typeof p.item === 'number' ? p.item : fallback;
}

// ===== src/lib/gemini.js =====

// Google Gemini REST helpers (free tier via Google AI Studio API key).
// The HTTP Request node posts `ai_body` to `request_url`; the API key is sent by
// an n8n "Header Auth" credential (header `x-goog-api-key`), never stored here.



const GEMINI_ENDPOINT = 'https://generativelanguage.googleapis.com/v1beta/models';

function geminiUrl(model) {
  const m = text(model);
  if (!/^[a-z0-9][a-z0-9.\-]*$/i.test(m)) throw new Error(`Invalid Gemini model name "${m}" in the Config node.`);
  return `${GEMINI_ENDPOINT}/${m}:generateContent`;
}

function geminiBody(prompt, { temperature = 0.2, maxOutputTokens = 2048 } = {}) {
  return {
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: { temperature, maxOutputTokens, responseMimeType: 'application/json' },
  };
}

// Returns { ok: true, value } or { ok: false, error } and never throws.
function parseGeminiJson(response) {
  const r = response || {};
  if (r.error) {
    const msg = typeof r.error === 'string' ? r.error : text(r.error.message) || JSON.stringify(r.error);
    return { ok: false, error: `AI request failed: ${msg.slice(0, 300)}` };
  }
  const candidate = Array.isArray(r.candidates) ? r.candidates[0] : null;
  const parts = candidate && candidate.content && Array.isArray(candidate.content.parts) ? candidate.content.parts : [];
  const raw = parts.map((p) => (p && typeof p.text === 'string' ? p.text : '')).join('').trim();
  if (!raw) {
    const reason = candidate ? text(candidate.finishReason) : text(r.promptFeedback && r.promptFeedback.blockReason);
    return { ok: false, error: `AI returned no content${reason ? ` (${reason})` : ''}` };
  }
  const unfenced = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try {
    const value = JSON.parse(unfenced);
    if (!value || typeof value !== 'object' || Array.isArray(value)) return { ok: false, error: 'AI JSON is not an object' };
    return { ok: true, value };
  } catch (e) {
    return { ok: false, error: `AI returned invalid JSON: ${e.message.slice(0, 120)}` };
  }
}

// ===== src/lib/registries.js =====

// Company-registry verification, routed by the lead's country (WF02).
//
// Each country has an adapter with the same shape:
//   provider   identifier stored in Leads.registry_provider
//   live       true only when the official source has been implemented AND tested;
//              a non-live adapter never makes a request and always returns UNVERIFIED
//   plan(ctx)  -> { request_url, source_url, matched_by } or { skip }
//   evaluate(plan, response) -> verification result
//
// Results are deliberately conservative. No match, an ambiguous match, an API
// failure, an unsupported country or a non-live adapter all give UNVERIFIED, which
// means "we could not confirm it", never "the business does not exist".
// INELIGIBLE is used only when the registry record is identified by company
// number and itself says the company is not active or not an eligible type.
//
// Embedded into WF02's Code nodes after common.js (IMPORTS/EXPORT stripped).



const REGISTRY_STATUS = {
  VERIFIED: 'VERIFIED',
  MANUAL_VERIFIED: 'MANUAL_VERIFIED',
  INELIGIBLE: 'INELIGIBLE',
  UNVERIFIED: 'UNVERIFIED',
};

// Leads columns that hold the registry result (appended to the end of Leads).
const REGISTRY_COLUMNS = [
  'registry_country', 'registry_provider', 'registry_status', 'registry_source_url',
  'registry_checked_at', 'registry_match_rationale',
];

const COUNTRY_ALIASES = {
  GB: ['gb', 'uk', 'united kingdom', 'great britain', 'england', 'scotland', 'wales', 'northern ireland', 'england and wales'],
  US: ['us', 'usa', 'united states', 'united states of america', 'u.s.', 'u.s.a.'],
  IN: ['in', 'ind', 'india', 'bharat'],
};

// ISO 3166-1 alpha-2 code, or '' if the value isn't recognisable.
function normaliseCountry(value) {
  const v = text(value).toLowerCase();
  if (!v) return '';
  for (const [code, aliases] of Object.entries(COUNTRY_ALIASES)) if (aliases.includes(v)) return code;
  return /^[a-z]{2}$/.test(v) ? v.toUpperCase() : '';
}

function errorMessage(response) {
  const e = response && response.error;
  if (!e) return '';
  return typeof e === 'string' ? e : text(e.message) || text(e.description) || JSON.stringify(e);
}

function normaliseCompanyName(name) {
  return text(name)
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\b(the|limited|ltd|llp|plc|company|co)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normaliseUkCompanyNumber(value) {
  const v = text(value).toUpperCase().replace(/\s+/g, '');
  if (/^\d{1,8}$/.test(v)) return v.padStart(8, '0');
  if (/^(SC|NI|OC|SO|NC|R0|NL|SL)\d{6}$/.test(v)) return v;
  return '';
}

// ---------- GB: Companies House (official, free API key) ----------

const CH_API = 'https://api.company-information.service.gov.uk';
const CH_WEB = 'https://find-and-update.company-information.service.gov.uk';
// Companies House `type` values that count as "limited company or LLP".
const UK_ELIGIBLE_TYPES = new Set([
  'ltd', 'llp', 'plc', 'private-limited-guarant-nsc', 'private-limited-guarant-nsc-limited-exemption',
  'private-limited-shares-section-30-exemption',
]);

const companiesHouse = {
  provider: 'companies_house',
  live: true,
  requestField: 'ch_request_url',
  plan({ companyName, companyNumber, numberSource }) {
    const number = normaliseUkCompanyNumber(companyNumber);
    if (number) {
      return {
        request_url: `${CH_API}/company/${encodeURIComponent(number)}`,
        source_url: `${CH_WEB}/company/${encodeURIComponent(number)}`,
        matched_by: `company number ${number} (${numberSource || 'given'})`,
        company_number: number,
      };
    }
    if (!text(companyName)) return { skip: 'no company name or company number to look up' };
    const q = encodeURIComponent(text(companyName));
    return {
      request_url: `${CH_API}/search/companies?q=${q}&items_per_page=5`,
      source_url: `${CH_WEB}/search/companies?q=${q}`,
      matched_by: 'exact company-name search',
      company_name: text(companyName),
    };
  },
  evaluate(plan, response) {
    const r = response || {};
    const err = errorMessage(r);
    if (err) {
      return { status: REGISTRY_STATUS.UNVERIFIED, rationale: `Companies House lookup by ${plan.matched_by} failed (${clip(err, 160)}). This does not mean the company is unregistered.` };
    }
    if (text(r.company_number) && text(r.company_status)) {
      const rec = { number: text(r.company_number), status: text(r.company_status), type: text(r.type), name: text(r.company_name) };
      const facts = `${rec.name || 'record'} (${rec.number}), status "${rec.status}", type "${rec.type}"`;
      const company = { company_number: rec.number, company_status: rec.status, legal_entity_type: rec.type };
      const sourceUrl = `${CH_WEB}/company/${encodeURIComponent(rec.number)}`;
      if (rec.status !== 'active') return { status: REGISTRY_STATUS.INELIGIBLE, rationale: `Matched by ${plan.matched_by}: ${facts}. Not active.`, company, sourceUrl };
      if (!UK_ELIGIBLE_TYPES.has(rec.type)) return { status: REGISTRY_STATUS.INELIGIBLE, rationale: `Matched by ${plan.matched_by}: ${facts}. Not a limited company or LLP.`, company, sourceUrl };
      return { status: REGISTRY_STATUS.VERIFIED, rationale: `Matched by ${plan.matched_by}: ${facts}.`, company, sourceUrl };
    }
    if (Array.isArray(r.items)) {
      const wanted = normaliseCompanyName(plan.company_name);
      const matches = r.items.filter((i) => i && normaliseCompanyName(i.title) === wanted);
      if (matches.length === 0) {
        return { status: REGISTRY_STATUS.UNVERIFIED, rationale: `No exact name match for "${plan.company_name}" among ${r.items.length} Companies House search result(s). The business may trade under a different legal name; this does not mean it is unregistered.` };
      }
      if (matches.length > 1) {
        return { status: REGISTRY_STATUS.UNVERIFIED, rationale: `Ambiguous: ${matches.length} Companies House companies share the name "${plan.company_name}" (${matches.map((m) => text(m.company_number)).join(', ')}).` };
      }
      const m = matches[0];
      const rec = { number: text(m.company_number), status: text(m.company_status), type: text(m.company_type), name: text(m.title) };
      const company = { company_number: rec.number, company_status: rec.status, legal_entity_type: rec.type };
      const sourceUrl = rec.number ? `${CH_WEB}/company/${encodeURIComponent(rec.number)}` : '';
      if (rec.status === 'active' && UK_ELIGIBLE_TYPES.has(rec.type)) {
        return { status: REGISTRY_STATUS.VERIFIED, rationale: `Exactly one Companies House result has the same name: ${rec.name} (${rec.number}), active, type "${rec.type}".`, company, sourceUrl };
      }
      // A name match is weaker than a number match: the inactive record may be a
      // different or former entity, so this is not proof of ineligibility.
      return { status: REGISTRY_STATUS.UNVERIFIED, rationale: `The only exact-name match is ${rec.name} (${rec.number}), status "${rec.status}", type "${rec.type}". It may be a different or former entity; check by hand.`, company, sourceUrl };
    }
    return { status: REGISTRY_STATUS.UNVERIFIED, rationale: 'Unexpected Companies House response; nothing could be confirmed.' };
  },
};

// ---------- US and IN: designed, not live ----------
// These adapters never make a request. They become live only when an official
// source, its terms and FlowHQ's credentials have been confirmed and tested.

const usStateRegistries = {
  provider: 'us_state_registry',
  live: false,
  plan() {
    return {
      skip: 'US company registration is held by each state (e.g. a Secretary of State business search). No official US registry source or credentials are configured for FlowHQ, so nothing was queried. Verify by hand with the relevant state registry.',
    };
  },
  evaluate() {
    return { status: REGISTRY_STATUS.UNVERIFIED, rationale: 'US registry adapter is not live.' };
  },
};

const indiaMca = {
  provider: 'mca_india',
  live: false,
  plan() {
    return {
      skip: "Indian company registration is held by the Ministry of Corporate Affairs (MCA). No official MCA data access or credentials are configured for FlowHQ, so nothing was queried. Verify by hand on the MCA portal.",
    };
  },
  evaluate() {
    return { status: REGISTRY_STATUS.UNVERIFIED, rationale: 'India registry adapter is not live.' };
  },
};

const REGISTRY_ADAPTERS = { GB: companiesHouse, US: usStateRegistries, IN: indiaMca };

// ---------- router ----------

// A human can record a manual check: registry_status = MANUAL_VERIFIED together
// with an http(s) registry_source_url and a registry_match_rationale.
function manualVerification(lead) {
  if (text(lead.registry_status) !== REGISTRY_STATUS.MANUAL_VERIFIED) return null;
  if (!parseHost(lead.registry_source_url, { requireScheme: true }) || !text(lead.registry_match_rationale)) return null;
  return lead;
}

function planRegistryLookup({ lead, country, companyNumber, numberSource }) {
  const code = normaliseCountry(country);
  const base = { country_code: code, provider: 'none', live: false, request_url: '', source_url: '', matched_by: '', skip: '' };
  const manual = manualVerification(lead || {});
  if (manual) return { ...base, provider: text(manual.registry_provider) || 'manual', manual: true };
  if (!code) return { ...base, skip: `Country "${text(country)}" is not recognised, so no registry could be chosen.` };
  const adapter = REGISTRY_ADAPTERS[code];
  if (!adapter) return { ...base, skip: `No registry adapter for country ${code}; registration was not checked.` };
  const plan = adapter.live ? adapter.plan({ companyName: lead && lead.company_name, companyNumber, numberSource }) : adapter.plan();
  return { ...base, ...plan, provider: adapter.provider, live: adapter.live, request_url: adapter.live && !plan.skip ? plan.request_url : '' };
}

// Turns a plan plus the HTTP response into the Leads registry columns.
function evaluateRegistry(plan, response, now) {
  const ts = text(now) || new Date().toISOString();
  const p = plan || {};
  const out = (status, rationale, sourceUrl, company) => ({
    registry_country: p.country_code || '',
    registry_provider: p.provider || 'none',
    registry_status: status,
    registry_source_url: text(sourceUrl),
    registry_checked_at: ts,
    registry_match_rationale: clip(rationale, 500),
    company: company || null,
  });
  if (p.manual) return { ...out(REGISTRY_STATUS.MANUAL_VERIFIED, '', '', null), manual: true };
  if (p.skip || !p.request_url) return out(REGISTRY_STATUS.UNVERIFIED, p.skip || 'No lookup was made.', '', null);
  const adapter = REGISTRY_ADAPTERS[p.country_code];
  const r = adapter.evaluate(p, response);
  return out(r.status, r.rationale, r.sourceUrl || p.source_url, r.company);
}

function isRegistryVerified(result) {
  return [REGISTRY_STATUS.VERIFIED, REGISTRY_STATUS.MANUAL_VERIFIED].includes(text(result && result.registry_status));
}

// A niche that names a legal-entity requirement needs a verified registry record.
function registryRequired(niche) {
  const v = text(niche && niche.legal_entity_required).toLowerCase();
  return Boolean(v) && v !== 'none';
}

// Leads columns to write: registry columns always, company columns when known.
// A manual verification keeps the human's values untouched.
function registryColumns(result, lead) {
  if (result.manual) {
    const keep = {};
    for (const c of REGISTRY_COLUMNS) keep[c] = lead[c] === undefined || lead[c] === null ? '' : lead[c];
    return keep;
  }
  const cols = {};
  for (const c of REGISTRY_COLUMNS) cols[c] = result[c];
  if (result.company) Object.assign(cols, result.company);
  return cols;
}

// ===== src/wf02-research-logic.js =====

// WF02 Research & Qualify: pure logic (docs/02-mvp-architecture.md §5, §6).
//
// Embedded after src/lib/common.js and src/lib/gemini.js into the Code nodes of
// workflows/WF02-research-qualify.json. IMPORTS and the EXPORT tail are stripped.
//
// Pipeline per lead: fetch homepage → fetch ≤2 internal pages (contact, about/team)
// → company-registry check routed by the lead's country (src/lib/registries.js)
// → Gemini scoring of the website → deterministic caps and hard gates → one
// Leads update. Website evidence (Leads.evidence) and legal registration
// (Leads.registry_*) are kept separate. Any step that can't complete leaves the
// lead in a state a human can see; nothing is qualified on unverified data.



const MAX_PAGE_CHARS = 6000;
const WEIGHTS = { fit: 30, problem: 30, contact: 20, channel: 20 };

// Mailbox names that indicate a shared role address rather than a person.
const ROLE_LOCAL_PARTS = new Set([
  'info', 'hello', 'hi', 'enquiries', 'enquiry', 'inquiries', 'sales', 'lettings', 'letting', 'rentals',
  'office', 'admin', 'contact', 'mail', 'reception', 'team', 'property', 'properties', 'homes',
  'valuations', 'valuation', 'accounts', 'support', 'help', 'general', 'post', 'lets', 'management',
  'pm', 'propertymanagement', 'maintenance', 'branch', 'newbusiness', 'marketing',
]);

// Columns WF02 owns in Leads (plus lead_id as the match key). Every update
// carries all of them so unchanged values are written back, never blanked.
const WF02_COLUMNS = [
  'lead_id', 'company_number', 'company_status', 'legal_entity_type', 'stage', 'fit_score',
  'problem_score', 'contact_score', 'channel_score', 'total_score', 'qualification_reasoning',
  'evidence', 'opportunity_hypothesis', 'disqualify_reason', 'contact_name', 'contact_role',
  'last_updated', 'last_error', ...REGISTRY_COLUMNS,
];

const NO_SOLICITATION_PATTERNS = [
  /\b(?:no|not accept(?:ing)?|do not (?:accept|want|send)|don't (?:accept|want|send))\b[^.\n]{0,40}\b(?:unsolicited|cold|sales|marketing)\b[^.\n]{0,30}\b(?:calls?|e-?mails?|contact|approaches|enquiries|solicitations?)\b/i,
  /\bunsolicited (?:sales |marketing )?(?:e-?mails?|calls?|approaches)\b[^.\n]{0,40}\b(?:not|won't|will not)\b/i,
];

function researchUpdate(lead, changes, now) {
  const out = {};
  for (const c of WF02_COLUMNS) out[c] = lead[c] === undefined || lead[c] === null ? '' : lead[c];
  return { ...out, ...changes, lead_id: text(lead.lead_id), last_updated: now };
}

function websiteUrl(raw) {
  const value = text(raw);
  return /^https?:\/\//i.test(value) ? value : `https://${value}`;
}

// ---------- step 1: choose the batch ----------

// Google Sheets silently ignores updates to columns a tab doesn't have, so WF02
// reads the Leads header row and refuses to run until every column it writes exists.
function assertLeadsHeader(leadsHeaderRows) {
  const header = realRows(leadsHeaderRows).find((r) => text(r.lead_id) === 'lead_id');
  if (!header) throw new Error('Could not read the Leads header row; research aborted.');
  const present = new Set(Object.values(header).map((v) => text(v)));
  const missing = WF02_COLUMNS.filter((c) => !present.has(c));
  if (missing.length) {
    throw new Error(`The Leads tab is missing columns: ${missing.join(', ')}. Add them at the end of the header row (docs/09 §2), then re-run. Research aborted.`);
  }
}

function selectResearchBatch({ settingsRows, nichesRows, leadsRows, suppressionRows, leadsHeaderRows, now }) {
  const timestamp = text(now) || new Date().toISOString();
  assertLeadsHeader(leadsHeaderRows);
  const settings = parseSettings(realRows(settingsRows));
  const niche = resolveActiveNiche(settings, realRows(nichesRows), 'research');
  const batchSize = parseIntSetting(settings.RESEARCH_BATCH_SIZE, 1, 25);
  if (Number.isNaN(batchSize)) throw new Error('Settings.RESEARCH_BATCH_SIZE must be a whole number from 1 to 25; research aborted.');
  const minScore = parseIntSetting(settings.MIN_QUALIFY_SCORE, 0, 100);
  if (Number.isNaN(minScore)) throw new Error('Settings.MIN_QUALIFY_SCORE must be a whole number from 0 to 100; research aborted.');

  const sup = buildSuppressionIndex(realRows(suppressionRows));
  const candidates = realRows(leadsRows)
    .filter((l) => text(l.stage) === STAGE.NEW && text(l.niche_id) === niche.niche_id && text(l.lead_id))
    // Leads that failed before go to the back of the queue so one bad site can't block the batch.
    .sort((a, b) => (text(a.last_error) ? 1 : 0) - (text(b.last_error) ? 1 : 0) || Number(a.row_number || 0) - Number(b.row_number || 0));

  const immediateUpdates = [];
  const researchItems = [];
  for (const lead of candidates) {
    const reason = suppressionReason(sup, lead.contact_email, lead.lead_id);
    if (reason) {
      immediateUpdates.push(researchUpdate(lead, { stage: STAGE.DISQUALIFIED, disqualify_reason: `Suppressed: ${reason}`, last_error: '' }, timestamp));
      continue;
    }
    if (researchItems.length >= batchSize) continue;
    const url = websiteUrl(lead.website);
    researchItems.push({
      lead_id: text(lead.lead_id),
      request_url: parseHost(url, { requireScheme: true }) ? url : '',
      website_url: url,
      // Registry routing uses the lead's own country; the niche's is the fallback.
      country: text(lead.country) || niche.country,
      niche: niche.row,
      min_score: minScore,
      lead,
    });
  }
  return { researchItems, immediateUpdates, activeNiche: niche.niche_id, summary: { queued: researchItems.length, suppressed: immediateUpdates.length, waiting: candidates.length - researchItems.length - immediateUpdates.length } };
}

// ---------- step 2: HTML handling ----------

const ENTITIES = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", rsquo: "'", lsquo: "'", ldquo: '"', rdquo: '"', ndash: '–', mdash: '—', pound: '£', hellip: '…', copy: '©' };

function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code > 0 && code < 0x110000 ? String.fromCodePoint(code) : ' ';
    }
    return Object.prototype.hasOwnProperty.call(ENTITIES, e.toLowerCase()) ? ENTITIES[e.toLowerCase()] : m;
  });
}

function htmlToText(html) {
  let s = String(html || '');
  s = s.replace(/<!--[\s\S]*?-->/g, ' ').replace(/<(script|style|noscript|svg|template|iframe)\b[\s\S]*?<\/\1\s*>/gi, ' ');
  s = s.replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|h[1-6]|tr|section|article|header|footer|address|td|dd|dt)\s*>/gi, '\n');
  s = decodeEntities(s.replace(/<[^>]+>/g, ' '));
  return s
    .split('\n')
    .map((line) => line.replace(/[ \t\r\f\v ]+/g, ' ').trim())
    .filter(Boolean)
    .join('\n');
}

// Cloudflare "email protection" hides addresses as hex XOR-encoded strings.
function decodeCfEmail(hex) {
  if (!/^[0-9a-f]+$/i.test(hex) || hex.length < 4 || hex.length % 2) return '';
  const key = parseInt(hex.slice(0, 2), 16);
  let out = '';
  for (let i = 2; i < hex.length; i += 2) out += String.fromCharCode(parseInt(hex.slice(i, i + 2), 16) ^ key);
  return out;
}

function emailsInHtml(html) {
  const found = new Set();
  const s = String(html || '');
  for (const m of s.matchAll(/mailto:([^"'?\s>]+)/gi)) found.add(normaliseEmail(decodeEntities(m[1])));
  for (const m of s.matchAll(/data-cfemail=["']([0-9a-f]+)["']/gi)) {
    const e = normaliseEmail(decodeCfEmail(m[1]));
    if (e) found.add(e);
  }
  for (const m of htmlToText(s).matchAll(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi)) found.add(normaliseEmail(m[0]));
  return [...found].filter((e) => e.includes('@'));
}

function resolveLink(href, base) {
  const h = decodeEntities(text(href));
  if (!h || /^(mailto|tel|javascript|data|sms|whatsapp):/i.test(h) || h.startsWith('#')) return '';
  const origin = /^(https?:\/\/[^/?#]+)/i.exec(base);
  if (!origin) return '';
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith('//')) return `https:${h}`;
  if (h.startsWith('/')) return origin[1] + h;
  return `${origin[1]}/${h.replace(/^\.\//, '')}`;
}

// Picks at most two internal pages: the best "contact" page and the best
// "about/team" page (architecture §6: homepage plus at most 2 pages).
function planPagesForLead(item, html) {
  const base = item.website_url;
  const leadDomain = text(item.lead_id).toLowerCase();
  const home = base.replace(/[?#].*$/, '').replace(/\/+$/, '');
  const picks = { contact: '', about: '' };
  for (const m of String(html || '').matchAll(/<a\b[^>]*?href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
    const url = resolveLink(m[1], base).replace(/#.*$/, '');
    if (!url || registrableDomain(parseHost(url)) !== leadDomain) continue;
    if (/\.(pdf|jpe?g|png|gif|webp|svg|docx?|xlsx?|zip|mp4)(\?|$)/i.test(url)) continue;
    if (url.replace(/\/+$/, '') === home) continue;
    const label = `${url} ${htmlToText(m[2])}`.toLowerCase();
    if (!picks.contact && /contact|get-in-touch|get in touch|enquir|find-us|find us/.test(label)) picks.contact = url;
    else if (!picks.about && /about|team|people|meet|our-story|our story|who-we-are|who we are/.test(label)) picks.about = url;
  }
  return [picks.contact, picks.about].filter(Boolean).map((url) => ({ lead_id: item.lead_id, request_url: url }));
}

function responseHtml(response) {
  const r = response || {};
  if (r.error) return { html: '', error: text(r.error.message || r.error) || 'request failed' };
  const data = typeof r.data === 'string' ? r.data : '';
  return data ? { html: data, error: '' } : { html: '', error: 'empty response' };
}

function findNoSolicitation(pages) {
  for (const p of pages) {
    for (const pattern of NO_SOLICITATION_PATTERNS) {
      const m = pattern.exec(p.text);
      if (m) {
        const start = Math.max(0, p.text.lastIndexOf('\n', m.index) + 1);
        const endNl = p.text.indexOf('\n', m.index + m[0].length);
        return { quote: clip(p.text.slice(start, endNl === -1 ? undefined : endNl), 240), url: p.url };
      }
    }
  }
  return null;
}

// Combines fetched pages into the research record and plans the registry lookup.
// The registry lookup doesn't depend on the website fetch succeeding.
function assembleResearch(item, homeResponse, pageResponses) {
  const home = responseHtml(homeResponse);
  const pages = [];
  const emails = new Set();
  if (home.html) {
    pages.push({ url: item.website_url, text: clip(htmlToText(home.html), MAX_PAGE_CHARS) });
    emailsInHtml(home.html).forEach((e) => emails.add(e));
  }
  for (const pr of pageResponses || []) {
    const r = responseHtml(pr.response);
    if (!r.html) continue;
    pages.push({ url: pr.url, text: clip(htmlToText(r.html), MAX_PAGE_CHARS) });
    emailsInHtml(r.html).forEach((e) => emails.add(e));
  }
  const fetchError = !item.request_url ? 'website is not a valid http(s) address' : home.html ? '' : `Website fetch failed: ${clip(home.error, 200)}`;
  const allText = pages.map((p) => p.text).join('\n');

  // A company number entered by a human wins over one found on the website.
  let companyNumber = text(item.lead.company_number);
  let numberSource = companyNumber ? 'entered in the Leads sheet' : '';
  if (!companyNumber) {
    const m = /(?:company|registration|registered|reg\.?)\s*(?:no\.?|number|num\.?|#)\s*[:.]?\s*((?:SC|NI|OC|SO|NC|R0)?\s?\d{6,8})\b/i.exec(allText);
    if (m) {
      companyNumber = m[1];
      numberSource = "found on the business's own website";
    }
  }
  const registryPlan = planRegistryLookup({ lead: item.lead, country: item.country, companyNumber, numberSource });

  return {
    ...item,
    pages,
    emails_found: [...emails],
    fetch_error: fetchError,
    company_number_hint: normaliseUkCompanyNumber(companyNumber) || text(companyNumber),
    no_solicitation: fetchError ? null : findNoSolicitation(pages),
    registry_plan: registryPlan,
    // Only the Companies House adapter has a live HTTP node; other countries leave this empty.
    ch_request_url: registryPlan.provider === 'companies_house' ? registryPlan.request_url : '',
  };
}

// ---------- step 3: AI request (website evidence only) ----------

function researchPrompt(assembled) {
  const n = assembled.niche || {};
  const pages = assembled.pages.map((p) => `=== PAGE URL: ${p.url} ===\n${p.text}`).join('\n\n');
  return [
    'You help FlowHQ, a small automation agency, decide whether a business is worth contacting.',
    'Use ONLY the page text provided below. Never use outside knowledge, never guess, never invent facts.',
    '',
    `Business: ${text(assembled.lead.company_name)} (${assembled.website_url})`,
    `Target niche: ${text(n.target_description)}`,
    `Pain signals to look for: ${text(n.pain_signals)}`,
    `Exclusions: ${text(n.exclusions)}`,
    `Decision-maker roles: ${text(n.decision_maker_roles)}`,
    `FlowHQ service: ${text(n.service_angle)}`,
    '',
    'Score each dimension with an integer 0-3:',
    'fit_score: 0 not in niche; 1 in niche but outside the size/type range; 2 in niche, size unclear; 3 in niche, independent, 1-3 branches.',
    'problem_score: 0 no signal found; 1 general inference only; 2 one public pain signal with an exact quote; 3 two or more signals with exact quotes.',
    'contact_score: 0 no contact; 1 generic inbox only; 2 a named person with a role on a team page; 3 a named decision-maker with a published email.',
    '',
    'Return ONLY this JSON object:',
    '{"fit_score":0,"problem_score":0,"contact_score":0,',
    '"qualification_reasoning":"2-4 factual sentences",',
    '"evidence":[{"quote":"text copied character-for-character from one page","url":"that PAGE URL","signal":"which pain signal it shows"}],',
    '"opportunity_hypothesis":"one sentence: the single FlowHQ automation most likely to help, phrased as a possibility",',
    '"decision_maker":{"name":"","role":"","quote":"","url":""},',
    '"exclusions_found":[{"exclusion":"","quote":"","url":""}],',
    '"no_solicitation_notice":{"found":false,"quote":"","url":""}}',
    'Quotes must be copied exactly (under 200 characters each). Leave a field empty rather than guessing. Use [] when nothing applies.',
    '',
    pages,
  ].join('\n');
}

function buildAiRequest(assembled, registry, model) {
  if (assembled.fetch_error) return { request_url: '', skip_reason: assembled.fetch_error };
  if (assembled.no_solicitation) return { request_url: '', skip_reason: 'no-solicitation notice found' };
  if (registry.registry_status === REGISTRY_STATUS.INELIGIBLE) return { request_url: '', skip_reason: registry.registry_match_rationale };
  if (registryRequired(assembled.niche) && !isRegistryVerified(registry)) return { request_url: '', skip_reason: `registration ${registry.registry_status}` };
  return { request_url: geminiUrl(model), ai_body: geminiBody(researchPrompt(assembled)) };
}

// ---------- step 4: scoring and gates ----------

function matchable(s) {
  return text(s).toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/\s+/g, ' ').trim();
}

function samePage(a, b) {
  return text(a).replace(/[#?].*$/, '').replace(/\/+$/, '').toLowerCase() === text(b).replace(/[#?].*$/, '').replace(/\/+$/, '').toLowerCase();
}

// A quote counts only if it appears verbatim on the page it cites.
function verifyQuote(pages, quote, url) {
  const q = matchable(quote);
  if (q.length < 10) return false;
  const page = pages.find((p) => samePage(p.url, url));
  return Boolean(page) && matchable(page.text).includes(q);
}

function clampScore(v) {
  const n = Number(v);
  return Number.isInteger(n) && n >= 0 && n <= 3 ? n : null;
}

function isRoleEmail(email) {
  const local = normaliseEmail(email).split('@')[0] || '';
  return ROLE_LOCAL_PARTS.has(local.replace(/[^a-z]/g, '')) || /\d/.test(local);
}

function channelScore(lead) {
  const email = normaliseEmail(lead.contact_email);
  if (!email) return 0;
  const d = registrableDomain(emailDomain(email));
  if (FREE_MAIL_DOMAINS.has(d) || isRoleEmail(email)) return 2;
  return d === text(lead.lead_id).toLowerCase() ? 3 : 2;
}

function scoreAndGate({ assembled, registry, aiResponse, now }) {
  const lead = assembled.lead;
  const timestamp = text(now) || new Date().toISOString();
  // The registry result is recorded on every path; it never touches Leads.evidence.
  const reg = registryColumns(registry, lead);
  const required = registryRequired(assembled.niche);

  if (assembled.fetch_error) {
    // The website wasn't analysed: keep the stage so the lead is retried, and say why.
    return researchUpdate(lead, { ...reg, last_error: clip(assembled.fetch_error, 300) }, timestamp);
  }
  if (assembled.no_solicitation) {
    const ns = assembled.no_solicitation;
    return researchUpdate(lead, { ...reg, stage: STAGE.DISQUALIFIED, disqualify_reason: clip(`No-solicitation notice: "${ns.quote}" (${ns.url})`, 500), last_error: '' }, timestamp);
  }
  if (registry.registry_status === REGISTRY_STATUS.INELIGIBLE) {
    return researchUpdate(lead, { ...reg, stage: STAGE.DISQUALIFIED, disqualify_reason: clip(`Registry (${registry.registry_provider}): ${registry.registry_match_rationale}`, 500), last_error: '' }, timestamp);
  }
  if (required && !isRegistryVerified(registry)) {
    return researchUpdate(lead, {
      ...reg,
      stage: STAGE.RESEARCHED,
      qualification_reasoning: clip(`Needs manual registry check (niche requires "${text(assembled.niche.legal_entity_required)}"; registry_status ${registry.registry_status}). See registry_match_rationale. Verify with the official registry, then either enter company_number (GB) or set registry_status = MANUAL_VERIFIED with registry_source_url and registry_match_rationale, and set stage back to "New Lead".`, 1000),
      last_error: clip(`Registration ${registry.registry_status}: ${registry.registry_match_rationale}`, 300),
    }, timestamp);
  }

  const ai = parseGeminiJson(aiResponse);
  if (!ai.ok) return researchUpdate(lead, { ...reg, last_error: clip(ai.error, 300) }, timestamp);
  const v = ai.value;
  const fit = clampScore(v.fit_score);
  const problemAi = clampScore(v.problem_score);
  const contactAi = clampScore(v.contact_score);
  if (fit === null || problemAi === null || contactAi === null) {
    return researchUpdate(lead, { ...reg, last_error: 'AI response invalid: scores must be integers 0-3' }, timestamp);
  }

  const pages = assembled.pages;
  const evidence = (Array.isArray(v.evidence) ? v.evidence : [])
    .filter((e) => e && verifyQuote(pages, e.quote, e.url))
    .slice(0, 5)
    .map((e) => ({ quote: clip(e.quote, 200), url: text(e.url), signal: clip(e.signal, 60) }));
  const droppedEvidence = (Array.isArray(v.evidence) ? v.evidence.length : 0) - evidence.length;

  // Architecture §5: problem evidence above 1 needs quotes + URLs.
  const problemCap = evidence.length === 0 ? 1 : evidence.length === 1 ? 2 : 3;
  const problem = Math.min(problemAi, problemCap);

  let contactName = text(lead.contact_name);
  let contactRole = text(lead.contact_role);
  const dm = v.decision_maker || {};
  if (!contactName && text(dm.name) && verifyQuote(pages, dm.quote, dm.url) && matchable(dm.quote).includes(matchable(dm.name))) {
    contactName = clip(dm.name, 80);
    contactRole = clip(dm.role, 80);
  }
  const channel = channelScore(lead);
  const contactCap = channel === 0 ? 0 : !contactName ? 1 : isRoleEmail(lead.contact_email) ? 2 : 3;
  const contact = Math.min(contactAi, contactCap);

  const total = Math.round((fit / 3) * WEIGHTS.fit + (problem / 3) * WEIGHTS.problem + (contact / 3) * WEIGHTS.contact + (channel / 3) * WEIGHTS.channel);
  const overrideRaw = text(lead.score_override);
  const override = /^\d{1,3}$/.test(overrideRaw) && Number(overrideRaw) <= 100 ? Number(overrideRaw) : null;
  const effective = override === null ? total : override;

  const gates = [];
  if (channel === 0) gates.push('no published email (channel score 0)');
  const ns = v.no_solicitation_notice || {};
  if (ns.found === true && verifyQuote(pages, ns.quote, ns.url)) gates.push(`no-solicitation notice: "${clip(ns.quote, 160)}"`);
  for (const ex of Array.isArray(v.exclusions_found) ? v.exclusions_found : []) {
    if (ex && text(ex.exclusion) && verifyQuote(pages, ex.quote, ex.url)) gates.push(`exclusion "${clip(ex.exclusion, 60)}": "${clip(ex.quote, 160)}"`);
  }

  const notes = [];
  if (!isRegistryVerified(registry)) notes.push(`registration ${registry.registry_status} (not required for this niche)`);
  if (droppedEvidence > 0) notes.push(`${droppedEvidence} AI quote(s) discarded because they were not found verbatim on the cited page`);
  if (override !== null) notes.push(`score_override ${override} used instead of computed ${total}`);
  const reasoning = clip([text(v.qualification_reasoning), ...notes].filter(Boolean).join(' | '), 1500);

  let stage = STAGE.QUALIFIED;
  let disqualify = '';
  if (gates.length) {
    stage = STAGE.DISQUALIFIED;
    disqualify = clip(`Hard gate: ${gates.join('; ')}`, 500);
  } else if (effective < assembled.min_score) {
    stage = STAGE.DISQUALIFIED;
    disqualify = `Score ${effective} is below MIN_QUALIFY_SCORE ${assembled.min_score}`;
  }

  return researchUpdate(lead, {
    ...reg,
    stage,
    fit_score: fit,
    problem_score: problem,
    contact_score: contact,
    channel_score: channel,
    total_score: total,
    qualification_reasoning: reasoning,
    evidence: formatEvidence(evidence),
    opportunity_hypothesis: clip(v.opportunity_hypothesis, 300),
    disqualify_reason: disqualify,
    contact_name: contactName,
    contact_role: contactRole,
    last_error: '',
  }, timestamp);
}

// ---- n8n glue ----
const research = $('Research Items').all().map((i) => i.json);
const out = [];
$input.all().forEach((item, i) => {
  const src = research[pairedIndex(item, i)];
  const html = !item.json.error && typeof item.json.data === 'string' ? item.json.data : '';
  if (src) planPagesForLead(src, html).forEach((p) => out.push({ json: p }));
});
return out;

